#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    // Doolittle LU without pivoting:
    // After factorization:
    // - U is stored on and above diagonal in A
    // - L is stored below diagonal in A with implicit 1s on diagonal
    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // Compute L column entries below the pivot: A[i,k] /= pivot for i=k+1..N-1
        #pragma omp parallel for default(none) shared(A, N, k, pivot) schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k) + 1; ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            A[static_cast<size_t>(ii) * N + k] /= pivot;
        }

        // Update trailing submatrix: A[i,j] -= A[i,k] * A[k,j] for i,j > k
        #pragma omp parallel for collapse(2) default(none) shared(A, N, k) schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k) + 1; ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            for (std::ptrdiff_t jj = static_cast<std::ptrdiff_t>(k) + 1; jj < static_cast<std::ptrdiff_t>(N); ++jj) {
                const size_t i = static_cast<size_t>(ii);
                const size_t j = static_cast<size_t>(jj);
                A[i * N + j] -= A[i * N + k] * A[k * N + j];
            }
        }
    }
}
